package core

type ProbeAuth struct {
	Port     int    `json:"port"`
	User     string `json:"user"`
	Password string `json:"password"`
}

// CompileProbe cannot create TUN or direct outbounds. Probe credentials are
// ephemeral and must be freshly generated by the probe process coordinator.
func CompileProbe(node ProxyNode, auth ProbeAuth) (map[string]any, error) {
	if auth.Port < 1024 || auth.Port > 65535 || jsUTF16Length(auth.User) < 1 || jsUTF16Length(auth.User) > 255 || jsUTF16Length(auth.Password) < 16 || jsUTF16Length(auth.Password) > 255 {
		return nil, NewAppError("INVALID_INPUT")
	}
	outbound, err := CompileOutbound(node)
	if err != nil {
		return nil, err
	}
	return map[string]any{
		"log":       map[string]any{"loglevel": "none", "access": "none", "error": "none"},
		"inbounds":  []any{map[string]any{"tag": "health", "listen": "127.0.0.1", "port": auth.Port, "protocol": "socks", "settings": map[string]any{"auth": "password", "accounts": []any{map[string]any{"user": auth.User, "pass": auth.Password}}, "udp": false}}},
		"outbounds": []any{outbound},
		"routing":   map[string]any{"domainStrategy": "AsIs", "rules": []any{map[string]any{"type": "field", "inboundTag": []string{"health"}, "outboundTag": "proxy"}}},
	}, nil
}
